package dev.zomboid.firstaid;import java.util.*;import fixture.*;import net.minecraft.world.entity.player.Player;
public class AidChecks{
 static int checks;static void ok(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}
 public static class Part{public float currentHealth,max=10;Part(float hp){currentHealth=hp;}public int getMaxHealth(){return 10;}public float heal(float n,Object p,boolean sim){float amount=Math.min(n,max-currentHealth);if(!sim)currentHealth+=amount;return amount;}}
 public static class Model implements Iterable<Object>{public boolean criticalConditionActive=true,fail;public List<Object> parts=new ArrayList<>();public int normal,defib,penalties,sync,resync;public Model(){for(int i=0;i<8;i++)parts.add(new Part(0));}public Iterator<Object> iterator(){return parts.iterator();}public boolean rescueFromCriticalState(Object p,Object healer,boolean delay){ok(Assist.allowed(this),"native allowed-completing guard enabled");normal++;return !fail;}public boolean defibrillatorRescueFromCriticalState(Object p,boolean delay){ok(Assist.allowed(this),"defib guard enabled");defib++;return !fail;}public void clearUnconsciousState(){}public void clearUnconsciousPenalties(Object p){penalties++;}public void syncVanillaHealth(Object p){sync++;}public void scheduleResync(){resync++;}}
 public static void main(String[]args){World world=new World();Player p=new Player(world);Model model=new Model();Assist.models.put(p,model);world.now=100;Object previous=new Object();Assist.completing=previous;ok(NpcAid7.down(p),"native downed status");ok(NpcAid7.revive(p,false),"manual NPC CPR succeeds through real bridge");ok(model.normal==1&&model.defib==0&&!model.criticalConditionActive,"manual native rescue selected");ok(Assist.completing==previous,"completing guard restored");ok(p.wakes==1&&p.dimensions==1&&model.sync==1&&model.resync==1,"native wake, posture and model resync");ok(p.tag.getLong("FABleedGraceUntil")==500&&p.tag.getLong("FADownDeadline")==0,"bleed grace and deadline cleanup");for(Object part:model.parts)ok(((Part)part).currentHealth==3,"parts restored to 30 percent, not full healing");ok(!NpcAid7.revive(p,false),"cannot repeatedly revive conscious player");float missing=NpcAid7.missing(p);ok(missing==56,"missing-health queries actual First Aid parts");ok(NpcAid7.heal(p,5),"bandage heals actual part");ok(NpcAid7.missing(p)==51,"only five points healed");for(Object part:model.parts)((Part)part).currentHealth=10;ok(!NpcAid7.heal(p,5),"no treatment consumed for healthy player");
  Model defib=new Model();Assist.models.put(p,defib);ok(NpcAid7.revive(p,true)&&defib.defib==1&&defib.normal==0,"NPC-owned defib native rescue branch");Model failed=new Model();failed.fail=true;Assist.models.put(p,failed);ok(!NpcAid7.revive(p,false)&&Assist.completing==previous,"failed rescue restores guard");p.alive=false;ok(!NpcAid7.revive(p,false),"no resurrection after actual death");System.out.println("NPC_FIRSTAID_BRIDGE_CHECKS="+checks);
 }
}
